import { test as base, expect, type Page, type Locator } from "@playwright/test";

/**
 * Shared helpers for the StorePage end-to-end suite.
 *
 * These helpers deliberately avoid hard-coded ids/classes generated by
 * Tailwind or Radix; they lean on accessible roles and text so the specs
 * break only when real user-facing behaviour changes.
 */

/** Console messages that are noise in this app and must not fail a spec. */
const BENIGN_CONSOLE_PATTERNS: RegExp[] = [
    // next/image perf hints emitted by product cards using `fill`.
    /has "fill" but is missing "sizes" prop/i,
    /has "fill" and parent element with invalid "position"/i,
    // Third-party CDN / font / favicon / analytics probes that can fail in
    // headless or sandboxed runs (blocked by CSP, ad-blockers, offline).
    /favicon/i,
    /Failed to load resource: the server responded with a status of (403|404)/i,
    /net::ERR_/i,
    /googletagmanager|google-analytics|gtag/i,
    // React dev-mode hydration chatter.
    /Download the React DevTools/i,
    /Warning: ReactDOM.render/i,
    /Hydration failed/i,
];

/**
 * Extended `test` fixture that fails a spec if the page logged an unexpected
 * console error or threw an uncaught page error. Benign next/image and
 * dev-only noise is filtered out.
 *
 * Usage:  import { test, expect } from "./utils";
 */
export const test = base.extend<{ consoleGuard: void }>({
    consoleGuard: [
        async ({ page }, use) => {
            const errors: string[] = [];

            page.on("console", (msg) => {
                if (msg.type() !== "error") return;
                const text = msg.text();
                if (BENIGN_CONSOLE_PATTERNS.some((re) => re.test(text))) return;
                errors.push(text);
            });

            page.on("pageerror", (err) => {
                if (BENIGN_CONSOLE_PATTERNS.some((re) => re.test(err.message))) return;
                errors.push(`pageerror: ${err.message}`);
            });

            await use();

            expect(
                errors,
                `Unexpected console/page errors:\n${errors.join("\n")}`,
            ).toEqual([]);
        },
        { auto: true },
    ],
});

export { expect };
export type { Page, Locator };

/**
 * The main site header.
 *
 * NOTE: the app's nav is a plain fixed `<div>` (see
 * `defaults/home-nav/ParentNav.tsx`) — there is no `<header>` landmark, so
 * `getByRole("banner")` finds nothing. Scope to the fixed top container that
 * wraps the brand link instead.
 */
export function siteHeader(page: Page): Locator {
    return page
        .locator("div.fixed.top-0")
        .filter({ has: page.getByRole("link", { name: /Store Page home/i }) })
        .first();
}

/** The brand/home link in the header (always present on storefront pages). */
export function brandLink(page: Page): Locator {
    return page.getByRole("link", { name: /Store Page home/i }).first();
}

/**
 * Header link that lands on the dashboard (or profile when signed in).
 *
 * The app renders TWO account links: one in the desktop header
 * (`NavTopSection`) and one inside the mobile drawer (`MobileDrawer`,
 * `md:hidden`). The drawer copy is in the DOM but not visible at desktop
 * width, so filter to the visible one instead of blindly taking `.first()`.
 */
export function accountLink(page: Page): Locator {
    return page.getByRole("link", { name: "Account" }).filter({ visible: true }).first();
}

/** The visible desktop "Sign in" nav link (distinct from the form button). */
export function headerSignInLink(page: Page): Locator {
    return page
        .getByRole("link", { name: "Sign in", exact: true })
        .filter({ visible: true })
        .first();
}

/**
 * Open the mobile side-menu if the viewport is narrow.
 * The header renders an "Open menu" button only under the `md` breakpoint.
 */
export async function openMobileMenuIfPresent(page: Page): Promise<void> {
    const menuButton = page.getByRole("button", { name: "Open menu" });
    if (await menuButton.isVisible().catch(() => false)) {
        await menuButton.click();
    }
}

/**
 * Wait until the home page has painted its server-rendered content.
 * The home route is statically generated, so "Explore Categories" is a
 * stable readiness marker.
 */
export async function waitForStorefrontReady(page: Page): Promise<void> {
    await expect(page.getByRole("heading", { name: "Explore Categories" })).toBeVisible({
        timeout: 20_000,
    });
}

/**
 * A category tile on the home page ("Laptop", "Phone", ...). Tiles are
 * clickable generic containers rather than links, so scope by the icon's
 * accessible image name and walk up to the interactive ancestor.
 */
export function categoryTile(page: Page, name: string): Locator {
    return page
        .getByRole("img", { name, exact: true })
        .locator("xpath=ancestor::*[@cursor='pointer' or @role='button'][1]");
}

/** Section wrapper around the "Featured Products" heading. */
export function featuredProductsSection(page: Page): Locator {
    return page.getByText("Featured Products").first().locator("xpath=..");
}

/**
 * Assert the browser actually navigated to `path` (allowing a trailing slash
 * and query string) and that the resulting document rendered.
 */
export async function expectPath(page: Page, path: string): Promise<void> {
    const escaped = path.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    await expect(page).toHaveURL(new RegExp(`${escaped}/?(\\?.*)?$`));
}
